css:
@font-face{font-family:'Lilita';src:url(node_modules/@fontsource/lilita-one/files/lilita-one-latin-400-normal.woff2)}
@font-face{font-family:'Outfit';font-weight:500;src:url(node_modules/@fontsource/outfit/files/outfit-latin-500-normal.woff2)}
@font-face{font-family:'Outfit';font-weight:700;src:url(node_modules/@fontsource/outfit/files/outfit-latin-700-normal.woff2)}
@font-face{font-family:'Outfit';font-weight:800;src:url(node_modules/@fontsource/outfit/files/outfit-latin-800-normal.woff2)}
.card{background:#3A2218;color:#F7EDE2;font-family:'Outfit';
 background-image:repeating-linear-gradient(90deg,rgba(0,0,0,.18) 0 6px,transparent 6px 180px),repeating-linear-gradient(0deg,rgba(0,0,0,.18) 0 6px,transparent 6px 180px);}
.card::before,.card::after{content:'';position:absolute;left:0;right:0;height:70px;background:#FF5F8F;
 background-image:repeating-linear-gradient(45deg,#E8457A 0 22px,#FF5F8F 22px 44px);z-index:0}
.card::before{top:0}.card::after{bottom:0}
.safe{z-index:1}
.kicker{font:800 40px 'Outfit';letter-spacing:6px;text-transform:uppercase;color:#FF8FB1;margin:0 0 30px}
h1{font-family:'Lilita';font-weight:400;font-size:140px;line-height:1.0;margin:0;color:#F7EDE2}
h1 em{font-style:normal;color:#FF8FB1}
.foil{background:#E4E6E8;color:#2B1810;border:6px solid #2B1810;border-radius:28px;padding:40px 46px;box-shadow:14px 14px 0 #1C0F0A;margin:0 0 34px}
.foil p{font:500 66px/1.22 'Outfit';margin:0}
.foil b{font-weight:800}
.tag{display:inline-block;align-self:flex-start;background:#FF5F8F;color:#2B1810;font:800 44px 'Outfit';padding:12px 26px;border-radius:999px;margin:0 0 36px;letter-spacing:2px;text-transform:uppercase}
.big{font-family:'Lilita';font-size:250px;line-height:.95;margin:0 0 24px;color:#FF8FB1}
.lbl{font:500 62px/1.25 'Outfit';margin:0 0 26px;color:#F7EDE2;max-width:820px}
.lbl b{color:#FFFFFF;font-weight:800}
.chain{display:flex;flex-direction:column;gap:0}
.node{background:#E4E6E8;color:#2B1810;border:6px solid #2B1810;border-radius:24px;padding:22px 34px;box-shadow:10px 10px 0 #1C0F0A}
.node b{font:400 76px 'Lilita';display:block;line-height:1.05}
.node span{font:500 48px/1.2 'Outfit'}
.node.pink{background:#FF8FB1}
.arrow{font:400 64px 'Lilita';color:#FF8FB1;margin:2px 0 2px 40px;line-height:1}
.card-1{background-color:#FF5F8F;background-image:none}
.card-1 h1{color:#2B1810;font-size:150px}
.card-1 .kicker{color:#2B1810}
.card-1 .wrapper{background:#3A2218;color:#F7EDE2;font:800 46px/1.25 'Outfit';padding:26px 34px;border-radius:20px;margin-top:50px;align-self:flex-start}
.card-1::before,.card-1::after{background:#3A2218;background-image:repeating-linear-gradient(45deg,#2B1810 0 22px,#3A2218 22px 44px)}
.end h1{font-size:118px}
.end .handle{font:800 56px 'Outfit';color:#FF8FB1;margin-top:46px}
.end p{font:500 52px/1.3 'Outfit';margin:24px 0 0}
